use super::*;
#[test]
fn original_timestamp_native_derivation_keeps_fixed_grant_receipts_and_original_input(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for value in law["values"].as_array().unwrap(){let epoch=value["epochMs"].as_i64().unwrap();for tag in [0,1,2]{if tag==1&&epoch<0{continue}let expected=value["expected"].as_str().unwrap();let mut source=vec![0xff,tag];let mut encoded=match tag{0=>expected.len()as u64,1=>epoch as u64,_=>((epoch<<1)^(epoch>>63))as u64};loop{let byte=(encoded&127)as u8;encoded>>=7;source.push(byte|if encoded==0{0}else{128});if encoded==0{break}}if tag==0{source.extend_from_slice(expected.as_bytes())}let end=source.len();source.push(0xfe);let original=source.as_ptr();
  for cancellation in [0,1,2,7,64]{let(result,heap)=observe(||RetainedWireFieldDecode::new_timestamp(&source,(1,end),if tag==2{Some(0)}else{None}));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut decoder=result.unwrap();assert_eq!(decoder.timestamp_epoch_millis(),if tag==0{None}else{Some(epoch)});let(mut birth,mut release,mut copied)=(0,0,0);let changed=source.clone();let(result,heap)=observe(||decoder.advance(&changed,grant));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
   for _ in 0..cancellation{if decoder.is_ready(){break}let demand=decoder.demands(&source,grant.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant}].into_iter().enumerate(){if(axis==2&&demand.capacity_bytes==0)||(axis==3&&demand.copy_bytes==0){continue}let(step,heap)=observe(||decoder.advance(&source,denied).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(decoder.receipt().is_none())}let(_,heap)=observe(||decoder.advance(&source,grant).unwrap());assert_eq!(decoder.source_identity(),(original as usize,source.len()));let(received,progress)=decoder.receipt().unwrap();assert_eq!(received,grant);assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress.copied_bytes<=2);birth+=heap.requested_bytes;release+=heap.released_bytes;copied+=progress.copied_bytes;let(step,heap)=observe(||decoder.advance(&source,grant).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));decoder.take_receipt().unwrap();}
   if cancellation==64{assert!(decoder.is_ready());let mut recipient=None;let(_,heap)=observe(||decoder.take_text_into(&mut recipient,grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(received,progress)=decoder.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!(progress.copied_bytes,0);assert_eq!(recipient.as_ref().unwrap(),expected);assert_eq!(copied,expected.len());release+=close_received_text(recipient,grant)}else{decoder.cancel();let demand=decoder.close_demands();if demand.release_bytes!=0{let(step,heap)=observe(||decoder.close_step(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(_,heap)=observe(||decoder.close_step(grant).unwrap());let(received,progress)=decoder.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));release+=heap.released_bytes;}
   assert!(decoder.terminal_is_empty());assert_eq!(birth,release);let(_,heap)=observe(||drop(decoder));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  }
 }}
 for source in [&[2,0][..],&[1,128][..],&[3,0][..],&[0,2,b'a'][..]]{let(result,heap)=observe(||RetainedWireFieldDecode::new_timestamp(source,(0,source.len()),None));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 eprintln!("[DEBUG] original tagged timestamps retain original scalar bytes and derive exactly funded2 byte native pieces, preserve unchanged full grants, conserve actual allocation/release receipts and cancel partial receiving owners with terminalDrop0");
}
